import React from 'react';
import { 
  LayoutDashboard, 
  Calendar, 
  BarChart3, 
  Trophy, 
  Settings, 
  Moon, 
  Sun,
  Flame
} from 'lucide-react';

interface SidebarProps {
  currentView: string;
  setCurrentView: (view: string) => void;
  darkMode: boolean;
  setDarkMode: (dark: boolean) => void;
  points: number;
  streak: number;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  currentView, 
  setCurrentView, 
  darkMode, 
  setDarkMode,
  points,
  streak
}) => {
  const menuItems = [
    { id: 'dashboard', label: "Dashboard", icon: LayoutDashboard },
    { id: 'calendar', label: "Calendar", icon: Calendar },
    { id: 'reports', label: "Analytics", icon: BarChart3 },
    { id: 'rewards', label: "Rewards", icon: Trophy },
    { id: 'settings', label: "Settings", icon: Settings },
  ];

  return (
    <aside className="w-64 glass border-r border-white/5 h-screen sticky top-0 flex flex-col p-4 z-50">
      <div className="flex items-center gap-3 px-2 mb-8 mt-2">
        <div className="w-10 h-10 bg-gradient-to-tr from-blue-600 to-purple-600 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/20">
          <Flame className="text-white fill-white animate-pulse" size={24} />
        </div>
        <div>
          <h1 className="text-xl font-bold tracking-tight">180-Day</h1>
          <p className="text-[10px] uppercase tracking-[0.2em] text-blue-400 font-semibold">Challenge Tracker</p>
        </div>
      </div>

      <nav className="flex-1 space-y-1">
        {menuItems.map((item) => {
          const Icon = item.icon;
          const isActive = currentView === item.id;
          return (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-300 ${
                isActive 
                  ? 'bg-blue-600/10 text-blue-400 border border-blue-500/20 shadow-[0_0_15px_rgba(59,130,246,0.1)]' 
                  : 'text-slate-400 hover:text-slate-200 hover:bg-white/5'
              }`}
            >
              <Icon size={20} className={isActive ? 'animate-pulse' : ''} />
              <span className="font-medium text-sm">{item.label}</span>
              {isActive && <div className="ml-auto w-1 h-1 bg-blue-400 rounded-full shadow-[0_0_8px_rgba(59,130,246,1)]" />}
            </button>
          );
        })}
      </nav>

      <div className="mt-auto pt-6 space-y-4">
        <div className="glass-card p-4 bg-gradient-to-br from-blue-600/10 to-purple-600/10 border-white/5">
          <div className="flex justify-between items-end mb-2">
            <div>
              <p className="text-[10px] uppercase tracking-wider text-slate-400 mb-1">Your Score</p>
              <p className="text-2xl font-bold text-white">{points}</p>
            </div>
            <div className="text-right">
              <p className="text-[10px] uppercase tracking-wider text-orange-400 mb-1">Streak</p>
              <div className="flex items-center gap-1">
                <Flame size={14} className="text-orange-500 fill-orange-500" />
                <p className="text-sm font-bold text-white">{streak}</p>
              </div>
            </div>
          </div>
          <div className="w-full bg-white/5 rounded-full h-1.5 mt-2">
            <div 
              className="bg-gradient-to-r from-blue-500 to-purple-500 h-full rounded-full transition-all duration-500"
              style={{ width: `${Math.min((streak / 30) * 100, 100)}%` }}
            />
          </div>
        </div>

        <button
          onClick={() => setDarkMode(!darkMode)}
          className="w-full flex items-center justify-between px-4 py-3 rounded-xl bg-white/5 hover:bg-white/10 transition-colors text-slate-400"
        >
          <div className="flex items-center gap-3">
            {darkMode ? <Moon size={20} /> : <Sun size={20} />}
            <span className="text-sm font-medium">{darkMode ? 'Dark Mode' : 'Light Mode'}</span>
          </div>
          <div className={`w-8 h-4 rounded-full relative transition-colors ${darkMode ? 'bg-blue-600' : 'bg-slate-600'}`}>
            <div className={`absolute top-0.5 w-3 h-3 rounded-full bg-white transition-all ${darkMode ? 'left-4.5' : 'left-0.5'}`} />
          </div>
        </button>
      </div>
    </aside>
  );
};

export default Sidebar;
